package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 *
 * A change made by a user acting for the steward who delegated the role to it ends each of its
 * records with for=<that steward>, except the records that only report figures (see {@link #FIGURES}).
 */
@Service
public class Audit {

    /** The events whose records only report figures: they never carry who a user acted for. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    /** A record's event, sheet and user: every record starts "EVENT sheet=<id> by=<user>". */
    private static final Pattern HEAD = Pattern.compile("^(\\S+) sheet=(.*?) by=(.*?)(?= [a-z][a-z-]*=|$)");

    private final Path file;
    private final ObjectProvider<ActingFor> actingFor;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<ActingFor> actingFor) {
        this.file = Path.of(path);
        this.actingFor = actingFor;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing. Outside a transaction the record is appended at once.
     */
    public void recordOnCommit(String record) {
        String entry = record + forWhom(record);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** " for=<steward>" when the record's user acts for a steward on the sheet's today, else nothing. */
    private String forWhom(String record) {
        Matcher head = HEAD.matcher(record);
        if (!head.find() || FIGURES.contains(head.group(1))) return "";
        ActingFor delegations = actingFor.getIfAvailable();
        if (delegations == null) return "";
        return delegations.actingFor(head.group(2), head.group(3)).map((steward) -> " for=" + steward).orElse("");
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.server.ResponseStatusException;

/**
 * Refuses every change asked for on an archived sheet: any request on a sheet other than reading it
 * (a GET, or loading the sheet) is refused before it reaches its controller, so it writes nothing.
 * As for a viewer, the bulk changes are let through and answered with every selected claim refused
 * (see {@code BulkChangeService}).
 */
@Component
public class ArchiveGuard implements HandlerInterceptor {

    private final SheetRepository sheets;

    public ArchiveGuard(SheetRepository sheets) {
        this.sheets = sheets;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod())) return true;
        String path = request.getRequestURI().substring(request.getContextPath().length());
        if (!path.startsWith(ViewerGuard.SHEETS)) return true;
        String rest = path.substring(ViewerGuard.SHEETS.length());
        int slash = rest.indexOf('/');
        if (slash < 0 || ViewerGuard.LET_THROUGH.contains(rest.substring(slash + 1))) return true;
        String sheetId = URLDecoder.decode(rest.substring(0, slash), StandardCharsets.UTF_8).trim();
        if (sheets.isArchived(sheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived: nothing on it can be changed.");
        }
        return true;
    }
}
package net.officefloor.hq.app;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.Set;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.server.ResponseStatusException;

/**
 * Refuses every change a viewer of a sheet asks for: any request on a sheet other than reading it
 * (a GET, or loading the sheet) is refused before it reaches its controller, so it writes nothing.
 * The bulk changes are let through: a viewer's bulk change is answered with every selected claim
 * refused (see {@code BulkChangeService}).
 */
@Component
public class ViewerGuard implements HandlerInterceptor {

    /** The path of a sheet's requests; the sheet id is the segment after it. */
    public static final String SHEETS = "/api/sheets/";

    static final Set<String> LET_THROUGH = Set.of("load", "claims/open", "claims/settle");

    private final SettingService settings;

    public ViewerGuard(SettingService settings) {
        this.settings = settings;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod())) return true;
        String path = request.getRequestURI().substring(request.getContextPath().length());
        String header = request.getHeader(SignedInUser.HEADER);
        if (!path.startsWith(SHEETS) || header == null || header.isBlank()) return true;
        String rest = path.substring(SHEETS.length());
        int slash = rest.indexOf('/');
        if (slash < 0 || LET_THROUGH.contains(rest.substring(slash + 1))) return true;
        String sheetId = URLDecoder.decode(rest.substring(0, slash), StandardCharsets.UTF_8).trim();
        if (settings.roleOf(sheetId, SignedInUser.name(header)) == Role.VIEWER) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer cannot change anything.");
        }
        return true;
    }
}
package net.officefloor.hq.app;

import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;

/** Who is signed in: the screen sends the typed name, URI-encoded, in a request header. */
public final class SignedInUser {

    /** The request header carrying the signed-in user's name. */
    public static final String HEADER = "X-User";

    private SignedInUser() {
    }

    /** The signed-in user's name from the header's value. */
    public static String name(String header) {
        return URLDecoder.decode(header.replace("+", "%2B"), StandardCharsets.UTF_8).trim();
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import net.officefloor.hq.app.SignedInUser;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets")
@Validated
public class SheetController {

    /** What the screen shows of a sheet. */
    public record SheetView(String id, LocalDate today, boolean archived) {
        static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday(), sheet.isArchived());
        }
    }

    /** A change of the sheet's today. */
    public record TodayChange(@NotNull LocalDate today) {
    }

    private final SheetService service;

    public SheetController(SheetService service) {
        this.service = service;
    }

    /** Load a sheet by id, starting it empty if it was never loaded before. */
    @PostMapping("/{id}/load")
    public SheetView load(@PathVariable @NotBlank @Size(max = 100) String id) {
        return SheetView.of(service.load(id.trim()));
    }

    /** Change the sheet's today. */
    @PutMapping("/{id}/today")
    public SheetView setToday(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid TodayChange change) {
        return SheetView.of(service.setToday(id.trim(), SignedInUser.name(user), change.today()));
    }

    /** Archive the sheet; a steward only. */
    @PostMapping("/{id}/archive")
    public SheetView archive(@PathVariable @NotBlank @Size(max = 100) String id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return SheetView.of(service.archive(id.trim(), SignedInUser.name(user)));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.Instant;
import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Rollup rollup;
    private final ApplicationEventPublisher events;
    private final Audit audit;
    // The settings read the sheet's today, so they are looked up when needed rather than injected.
    private final ObjectProvider<SettingService> settings;

    public SheetService(SheetRepository sheets, Rollup rollup, ApplicationEventPublisher events, Audit audit,
            ObjectProvider<SettingService> settings) {
        this.sheets = sheets;
        this.rollup = rollup;
        this.events = events;
        this.audit = audit;
        this.settings = settings;
    }

    /** The sheet with this id, as the store holds it now; a sheet never loaded before starts empty. */
    @Transactional
    public Sheet load(String id) {
        return sheets.findById(id).orElseGet(() -> create(id));
    }

    /**
     * The sheet's today. Every decision that depends on the date, and every default date, uses this
     * and never the real clock.
     */
    @Transactional
    public LocalDate today(String id) {
        return load(id).getToday();
    }

    /** Change the sheet's today; it has no audit line of its own, only what it sets off (such as the
     *  periods it closes) and then the figures it moves. */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id);
        Rollup.Snapshot before = rollup.snapshot(id);
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        events.publishEvent(new TodayChanged(id, user, today));
        rollup.recordChanges(user, before);
        return saved;
    }

    /** Archive the sheet: it stays visible, and every change on it is refused from then on (see
     *  {@code ArchiveGuard}). Refused to anyone but a steward of the sheet, and when it is archived. */
    @Transactional
    public Sheet archive(String id, String user) {
        load(id);
        Sheet sheet = sheets.findForUpdate(id).orElseThrow();
        if (settings.getObject().roleOf(id, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can archive the sheet.");
        }
        if (sheet.isArchived()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is already archived.");
        }
        sheet.archive();
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + id + " by=" + user);
        return saved;
    }

    /**
     * The sheet's next claim number: 1 for its first opened claim, then 2, and so on. The sheet stays
     * locked until the transaction ends, so two claims opened at once never share a number.
     */
    @Transactional
    public int nextClaimNumber(String id) {
        load(id);
        sheets.takeClaimNumber(id);
        return sheets.claimNumbersUsed(id);
    }

    /**
     * The next number of one of the sheet's per-period sequences (by key): 1 for its first, then 2,
     * and so on. The sheet stays locked until the transaction ends, so two claims opened at once
     * never share a number.
     */
    @Transactional
    public int nextSequenceNumber(String id, String key) {
        load(id);
        sheets.findForUpdate(id);
        Integer used = sheets.sequenceNumbersUsed(id, key);
        if (used == null) {
            sheets.startSequence(id, key);
            return 1;
        }
        sheets.takeSequenceNumber(id, key);
        return used + 1;
    }

    private Sheet create(String id) {
        try {
            // The only use of the real clock: a new sheet's today starts as the real date.
            return sheets.saveAndFlush(new Sheet(id, Instant.now(), LocalDate.now()));
        } catch (DataIntegrityViolationException raced) {
            // Another user loaded the same new id at the same moment.
            return sheets.findById(id).orElseThrow(() -> raced);
        }
    }
}
