import { HttpEvent, HttpInterceptorFn } from '@angular/common/http';
import { Observable, defer, finalize } from 'rxjs';

/** Settles once the last change sent so far has been answered. */
let lastChange: Promise<void> = Promise.resolve();

// Sends each change (any request but a read) only once the changes before it have been answered, so
// the store makes them, and records them in the audit file, in the order they were taken.
export const inOrderChangesInterceptor: HttpInterceptorFn = (req, next) => {
  if (req.method === 'GET' || req.method === 'HEAD') return next(req);
  const before = lastChange;
  let answered!: () => void;
  lastChange = new Promise<void>((resolve) => (answered = resolve));
  return new Observable<HttpEvent<unknown>>((subscriber) => {
    let sent = true;
    let inner: { unsubscribe(): void } | undefined;
    void before.then(() => {
      if (!sent) return;
      inner = defer(() => next(req)).pipe(finalize(answered)).subscribe(subscriber);
    });
    return () => {
      sent = false;
      if (inner) inner.unsubscribe();
      else void before.then(answered);
    };
  });
};
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

export interface SheetView {
  id: string;
  /** The sheet's today (yyyy-mm-dd): every date decision and default date uses it, never the real clock. */
  today: string;
  /** An archived sheet stays visible, and every change on it is refused. */
  archived: boolean;
}

// Who is signed in (a typed name, no password) and which sheet is active. Everything else in the
// app is kept per sheet and reads the active sheet id from here.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  private readonly userState = signal<string | null>(null);
  private readonly sheetState = signal<SheetView | null>(null);
  private readonly loadState = signal<SheetView | null>(null);

  readonly user = this.userState.asReadonly();
  readonly sheet = this.sheetState.asReadonly();
  /** The sheet as it was when it was last loaded: changes on each load, but not on a change of its
   *  today, so what is kept per sheet is re-read from the store only when a sheet is loaded. */
  readonly loaded = this.loadState.asReadonly();

  signIn(name: string): void {
    this.userState.set(name);
  }

  /** Load a sheet by id, re-read from the store; a sheet never loaded before starts empty. */
  async loadSheet(id: string): Promise<void> {
    const sheet = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null),
    );
    this.sheetState.set(sheet);
    this.loadState.set(sheet);
  }

  /** Change the active sheet's today; the store's answer replaces what the screen holds. */
  async setToday(today: string): Promise<void> {
    const current = this.sheetState();
    if (!current) throw new Error('No sheet is loaded.');
    const sheet = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(current.id)}/today`, { today }),
    );
    if (this.sheetState()?.id === sheet.id) this.sheetState.set(sheet);
  }

  /** Archive the active sheet; the store's answer replaces what the screen holds. */
  async archive(): Promise<void> {
    const current = this.sheetState();
    if (!current) throw new Error('No sheet is loaded.');
    const sheet = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(current.id)}/archive`, null),
    );
    if (this.sheetState()?.id === sheet.id) this.sheetState.set(sheet);
  }
}
import { HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { Session } from './session';

/** The header that tells the server who is signed in, so it can record who made each change. */
export const USER_HEADER = 'X-User';

// Sends the signed-in user's name (URI-encoded) with every request to the server.
export const signedInUserInterceptor: HttpInterceptorFn = (req, next) => {
  const user = inject(Session).user();
  return next(user ? req.clone({ setHeaders: { [USER_HEADER]: encodeURIComponent(user) } }) : req);
};
import { Component, effect, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';

// The active sheet's today, shown and changeable. Every date decision and default date in the app
// uses it, never the real clock. A steward can archive the sheet here too.
@Component({
  selector: 'app-sheet-today',
  imports: [ReactiveFormsModule],
  template: `
    @if (session.sheet(); as sheet) {
      <form [formGroup]="form" (ngSubmit)="save()" aria-label="Sheet today">
        <span>Today: <strong data-testid="sheet-today">{{ sheet.today }}</strong></span>
        <label for="sheet-today-input">Change today</label>
        <input id="sheet-today-input" type="date" data-testid="sheet-today-input" formControlName="today" />
        <button type="submit" data-testid="sheet-today-save" [disabled]="saving()">Set today</button>
        <span>Archived: <strong data-testid="sheet-archived">{{ sheet.archived ? 'yes' : 'no' }}</strong></span>
        <button type="button" data-testid="sheet-archive" [disabled]="saving()" (click)="archive()">Archive sheet</button>
        @if (error()) {
          <p role="alert" data-testid="sheet-error">{{ error() }}</p>
        }
      </form>
    }
  `,
})
export class SheetToday {
  protected readonly session = inject(Session);

  protected readonly today = new FormControl('', { nonNullable: true });
  protected readonly form = new FormGroup({ today: this.today });
  protected readonly saving = signal(false);
  protected readonly error = signal('');

  constructor() {
    this.today.valueChanges.subscribe(() => this.error.set(''));
    // A freshly loaded sheet starts the field at its today and clears any error from the last one.
    effect(() => {
      const sheet = this.session.sheet();
      this.error.set('');
      this.today.setValue(sheet?.today ?? '', { emitEvent: false });
    });
  }

  protected async save(): Promise<void> {
    // A second submit before the first has answered is ignored, so it stores one record, not two.
    if (this.saving()) return;
    const today = this.today.value.trim();
    this.error.set('');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.error.set('Type a date as yyyy-mm-dd.');
      return;
    }
    this.saving.set(true);
    try {
      await this.session.setToday(today);
    } catch {
      this.error.set("The sheet's today could not be changed.");
    } finally {
      this.saving.set(false);
    }
  }

  protected async archive(): Promise<void> {
    if (this.saving()) return;
    this.error.set('');
    this.saving.set(true);
    try {
      await this.session.archive();
    } catch {
      this.error.set('The sheet could not be archived.');
    } finally {
      this.saving.set(false);
    }
  }
}
import { Component, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';

// Choose the active sheet by typing its id and loading it.
@Component({
  selector: 'app-sheet-picker',
  imports: [ReactiveFormsModule],
  template: `
